table ip kube-proxy {
  chain services {
    type nat hook prerouting priority 0; policy accept;

    # ClusterIP Service
    ip daddr 10.96.0.1 tcp dport 80 jump service-nginx
  }

  chain service-nginx {
    # 负载均衡到 Endpoints
    numgen random mod 3 vmap {
      0: dnat to 10.244.1.2:80,
      1: dnat to 10.244.1.3:80,
      2: dnat to 10.244.1.4:80
    }
  }
}

